import * as bytes from "std/bytes";
import * as cli from "std/cli";
import * as fs from "std/fs";
import * as io from "std/io";

import * as messages from "local/marimay-notes/messages";
import * as notes from "local/marimay-notes/notes";

@test
fn databaseErrorsAreRussian(): void {
  const emptyText = notes.add(notes.empty(), " \t", []);
  expect.equal(
    match emptyText {
      Err(message) => message,
      Ok(_) => "",
    },
    "Текст заметки не должен быть пустым",
  );
  expect.equal(
    match notes.decode(bytes.encodeUtf8("{}")) {
      Err(message) => message,
      Ok(_) => "",
    },
    "Отсутствует обязательное поле «version»: байт 2; путь: $[\"version\"]",
  );
  expect.equal(
    match notes.decode(bytes.encodeUtf8("{\"version\":1,\"nextId\":1,\"notes\":null}")) {
      Err(message) => message,
      Ok(_) => "",
    },
    "Ожидается массив JSON: байт 32; путь: $[\"notes\"]",
  );
}

@test
fn commandAndSystemErrorsAreRussian(): void {
  expect.equal(
    messages.usageError(cli.UsageError.MissingOptionValue { name: "db", index: 0 }),
    "После --db нужно указать значение",
  );
  expect.equal(
    messages.usageError(cli.UsageError.UnknownOption { argument: "--нет", index: 0 }),
    "Неизвестный параметр «--нет». Справка: --help",
  );
  expect.equal(messages.fileError(fs.Error.NotFound), "Файл или каталог не найден");
  expect.equal(messages.ioError(io.Error.WriteFailed), "Не удалось вывести сообщение");
}

@test
fn russianNotesRoundTripWithoutChangingFormat(): void {
  const added = match notes.add(notes.empty(), "Купить чай ☕", ["дом", "покупки"]) {
    Ok(value) => value,
    Err(error) => panic(error),
  };
  const data = match notes.encode(added.database) {
    Ok(value) => value,
    Err(error) => panic(messages.jsonError(error)),
  };
  const restored = match notes.decode(data) {
    Ok(value) => value,
    Err(error) => panic(error),
  };
  expect.equal(restored.notes[0].text, "Купить чай ☕");
  expect.equal(restored.notes[0].tags[1], "покупки");
  expect.equal(restored.nextId, 2);
}

notes/api.my.text:
import * as bytes from "std/bytes";
import * as json from "std/json";
import * as text from "std/text";

import * as messages from "local/marimay-notes/messages";

public type Note {
  public id: int,
  public text: string,
  public tags: []string,
}

public type Database {
  public version: int,
  public nextId: int,
  public notes: []Note,
}

public type AddResult {
  public database: Database,
  public note: Note,
}

public fn empty(): Database {
  return Database { version: 1, nextId: 1, notes: [] };
}

public fn validate(database: Database): Result<void, string> {
  if database.version != 1 {
    return Err("Неподдерживаемая версия базы заметок");
  }
  if database.nextId < 1 {
    return Err("Значение nextId должно быть положительным");
  }
  const ids: Set<int> = setOf<int>();
  for note in database.notes {
    if note.id < 1 || note.id >= database.nextId {
      return Err("ID заметки должен быть положительным и меньше nextId");
    }
    if ids.contains(note.id) {
      return Err("В базе повторяется ID заметки");
    }
    const _ = ids.add(note.id);
  }
  return Ok();
}

public fn add(database: Database, value: string, tags: []string): Result<AddResult, string> {
  validate(database)?;
  if database.nextId == 9223372036854775807 {
    return Err("Свободные ID заметок закончились");
  }
  if text.trimAscii(value) == "" {
    return Err("Текст заметки не должен быть пустым");
  }
  let copied: []Note = [];
  for existing in database.notes {
    const _ = copied.push(existing);
  }
  const note = Note { id: database.nextId, text: value, tags };
  const _ = copied.push(note);
  return Ok(
    AddResult {
      database: Database { version: database.version, nextId: database.nextId + 1, notes: copied },
      note,
    },
  );
}

public fn find(database: Database, id: int): Option<Note> {
  for note in database.notes {
    if note.id == id {
      return Some(note);
    }
  }
  return None;
}

public fn remove(database: Database, id: int): bool {
  let found = -1;
  let index = 0;
  while index < database.notes.length() {
    if database.notes[index].id == id {
      found = index;
      break;
    }
    index += 1;
  }
  if found < 0 {
    return false;
  }
  index = found;
  while index < database.notes.length() - 1 {
    database.notes[index] = database.notes[index + 1];
    index += 1;
  }
  const _ = database.notes.truncate(database.notes.length() - 1);
  return true;
}

public fn decode(contents: bytes.Bytes): Result<Database, string> {
  const database = json.decode<Database>(contents).mapError(messages.jsonError)?;
  validate(database)?;
  return Ok(database);
}

public fn encode(database: Database): Result<bytes.Bytes, json.Error> {
  return json.encode(database);
}

notes/collection_baseline_test.my.text:
fn added(database: Database, value: string): AddResult {
  return match add(database, value, []) {
    Ok(result) => result,
    Err(error) => panic(error),
  };
}

@test
fn copyKeepsNoteIdentityAndTagAliases(): void {
  const note = Note { id: 1, text: "исходная", tags: ["до"] };
  const database = Database { version: 1, nextId: 2, notes: [note] };
  const result = added(database, "новая");
  expect.equal(database.notes.length(), 1);
  expect.equal(database.nextId, 2);
  expect.equal(result.database.notes.length(), 2);
  expect.true(identity.same(note, result.database.notes[0]));
  result.database.notes[0].tags[0] = "после";
  expect.equal(note.tags[0], "после");
  result.database.notes[0] = result.note;
  expect.true(identity.same(database.notes[0], note));
  expect.equal(database.notes[0].text, "исходная");
}

@test
fn removalPreservesOrderAndChangesArrayAliases(): void {
  const first = Note { id: 1, text: "одна", tags: [] };
  const middle = Note { id: 2, text: "две", tags: [] };
  const last = Note { id: 3, text: "три", tags: [] };
  const database = Database { version: 1, nextId: 4, notes: [first, middle, last] };
  const alias = database.notes;
  expect.true(remove(database, 2));
  expect.equal(alias.length(), 2);
  expect.true(identity.same(alias[0], first));
  expect.true(identity.same(alias[1], last));
  expect.equal(database.nextId, 4);
  expect.false(remove(database, 2));
  expect.equal(alias.length(), 2);
  expect.true(remove(database, 1));
  expect.true(identity.same(alias[0], last));
  expect.true(remove(database, 3));
  expect.equal(alias.length(), 0);
  expect.false(remove(database, 3));
}

@test
fn searchReturnsTheStoredRecord(): void {
  const first = Note { id: 2, text: "🌿", tags: ["язык"] };
  const last = Note { id: 8, text: "🌿", tags: [] };
  const database = Database { version: 1, nextId: 9, notes: [first, last] };
  const found = match find(database, 8) {
    Some(value) => value,
    None => panic("stored note was not found"),
  };
  expect.true(identity.same(found, last));
  expect.true(
    match find(database, 7) {
      Some(_) => false,
      None => true,
    },
  );
  expect.equal(database.notes.length(), 2);
}

@test
fn rejectedAddPreservesNonemptyInput(): void {
  const note = Note { id: 1, text: "сохранить", tags: ["важно"] };
  const database = Database { version: 1, nextId: 2, notes: [note] };
  expect.err(add(database, " \t", ["другой"]));
  expect.equal(database.notes.length(), 1);
  expect.equal(database.nextId, 2);
  expect.true(identity.same(database.notes[0], note));
  expect.equal(note.tags[0], "важно");
}

