import * as json from "std/json";

fn expectedValue(value: string): string {
  return match value {
    "a JSON string" => "строка JSON",
    "an escaped control character" => "экранированный управляющий символ",
    "a closing quote" => "закрывающая кавычка",
    "the end of a JSON literal" => "конец значения JSON",
    "the end of the current JSON container" => "конец текущего объекта или массива",
    "the end of input" => "конец файла",
    "true or false" => "true или false",
    "null" => "null",
    "an object" => "объект JSON",
    "an open object" => "открытый объект JSON",
    "a comma or closing brace" => "запятая или закрывающая фигурная скобка",
    "an object field after the comma" => "поле объекта после запятой",
    "a colon after the object field" => "двоеточие после имени поля",
    "an array" => "массив JSON",
    "an open array" => "открытый массив JSON",
    "a comma or closing bracket" => "запятая или закрывающая квадратная скобка",
    "an array element after the comma" => "элемент массива после запятой",
    _ => "корректное значение JSON",
  };
}

fn resourceName(value: string): string {
  return match value {
    "input bytes" => "размер входного файла в байтах",
    "output bytes" => "размер выходного файла в байтах",
    "string bytes" => "длина строки в байтах",
    "number bytes" => "длина записи числа",
    "nesting" => "глубина вложенности",
    "object fields" => "число полей объекта",
    "array items" => "число элементов массива",
    _ => "размер данных",
  };
}

fn baseJsonError(error: json.Error): string {
  return match error {
    InvalidLimits => "Некорректные ограничения JSON",
    InvalidUtf8 { path: _, span } => $"Некорректная кодировка UTF-8: байт {span.start}",
    UnexpectedToken {
      path: _,
      expected,
      span,
    } => $"Ожидается {expectedValue(expected)}: байт {span.start}",
    UnexpectedEnd {
      path: _,
      expected,
      span,
    } => $"Файл закончился раньше времени; ожидается {expectedValue(expected)}: байт {span.start}",
    InvalidEscape { path: _, span } => $"Некорректная escape-последовательность: байт {span.start}",
    InvalidUnicodeEscape {
      path: _,
      span,
    } => $"Некорректная escape-последовательность Unicode: байт {span.start}",
    InvalidNumber { path: _, span } => $"Некорректное число JSON: байт {span.start}",
    NumberOutOfRange {
      path: _,
      span,
    } => $"Число не помещается в 64-битное целое со знаком: байт {span.start}",
    DuplicateField { path: _, name, span } => $"Поле «{name}» повторяется: байт {span.start}",
    UnknownField { path: _, name, span } => $"Неизвестное поле «{name}»: байт {span.start}",
    MissingField {
      path: _,
      name,
      span,
    } => $"Отсутствует обязательное поле «{name}»: байт {span.start}",
    LimitExceeded {
      path: _,
      resource,
      limit,
      span,
    } => $"Превышено ограничение «{resourceName(resource)}»: {limit}; байт {span.start}",
    InvalidEncoderState { path: _, message } => "Внутренняя ошибка при формировании JSON",
  };
}

public fn jsonError(error: json.Error): string {
  const message = baseJsonError(error);
  if json.path(error).length() == 0 {
    return message;
  }
  return $"{message}; путь: {json.pathText(error)}";
}

