import * as bytes from "std/bytes";
import * as json from "std/json";
import * as text from "std/text";

import * as messages from "local/marimay-notes/messages";

public type Note {
  public id: int,
  public text: string,
  public tags: []string,
}

public type Database {
  public version: int,
  public nextId: int,
  public notes: []Note,
}

public type AddResult {
  public database: Database,
  public note: Note,
}

public fn empty(): Database {
  return Database { version: 1, nextId: 1, notes: [] };
}

fn collectionGrowthError(error: CollectionGrowthError): string {
  return match error {
    LengthLimit { limit } => $"Слишком много различных ID заметок: предел {limit}",
  };
}

public fn validate(database: Database): Result<void, string> {
  if database.version != 1 {
    return Err("Неподдерживаемая версия базы заметок");
  }
  if database.nextId < 1 {
    return Err("Значение nextId должно быть положительным");
  }
  const ids: Set<int> = setOf<int>();
  for note in database.notes {
    if note.id < 1 || note.id >= database.nextId {
      return Err("ID заметки должен быть положительным и меньше nextId");
    }
    const inserted = ids.add(note.id).mapError(collectionGrowthError)?;
    if !inserted {
      return Err("В базе повторяется ID заметки");
    }
  }
  return Ok();
}

public fn add(database: Database, value: string, tags: []string): Result<AddResult, string> {
  validate(database)?;
  if database.nextId == 9223372036854775807 {
    return Err("Свободные ID заметок закончились");
  }
  if text.trimAscii(value) == "" {
    return Err("Текст заметки не должен быть пустым");
  }
  let copied: []Note = [];
  for existing in database.notes {
    copied.push(existing).mapError(messages.arrayGrowthError)?;
  }
  const note = Note { id: database.nextId, text: value, tags };
  copied.push(note).mapError(messages.arrayGrowthError)?;
  return Ok(
    AddResult {
      database: Database { version: database.version, nextId: database.nextId + 1, notes: copied },
      note,
    },
  );
}

public fn find(database: Database, id: int): Option<Note> {
  for note in database.notes {
    if note.id == id {
      return Some(note);
    }
  }
  return None;
}

public fn remove(database: Database, id: int): bool {
  let found = -1;
  let index = 0;
  while index < database.notes.length() {
    if database.notes[index].id == id {
      found = index;
      break;
    }
    index += 1;
  }
  if found < 0 {
    return false;
  }
  index = found;
  while index < database.notes.length() - 1 {
    database.notes[index] = database.notes[index + 1];
    index += 1;
  }
  match database.notes.truncate(database.notes.length() - 1) {
    Ok(_) => {},
    Err(_) => panic("Внутренняя ошибка индекса при удалении заметки"),
  };
  return true;
}

public fn decode(contents: bytes.Bytes): Result<Database, string> {
  const database = json.decode<Database>(contents).mapError(messages.jsonError)?;
  validate(database)?;
  return Ok(database);
}

public fn encode(database: Database): Result<bytes.Bytes, json.Error> {
  return json.encode(database);
}

