@test
fn copyKeepsNoteIdentityAndTagAliases(): void {
  const note = Note { id: 1, text: "исходная", tags: ["до"] };
  const database = Database { version: 1, nextId: 2, notes: [note] };
  const result = added(database, "новая");
  expect.equal(database.notes.length(), 1);
  expect.equal(database.nextId, 2);
  expect.equal(result.database.notes.length(), 2);
  expect.true(identity.same(note, result.database.notes[0]));
  result.database.notes[0].tags[0] = "после";
  expect.equal(note.tags[0], "после");
  result.database.notes[0] = result.note;
  expect.true(identity.same(database.notes[0], note));
  expect.equal(database.notes[0].text, "исходная");
}

@test
fn removalPreservesOrderAndChangesArrayAliases(): void {
  const first = Note { id: 1, text: "одна", tags: [] };
  const middle = Note { id: 2, text: "две", tags: [] };
  const last = Note { id: 3, text: "три", tags: [] };
  const database = Database { version: 1, nextId: 4, notes: [first, middle, last] };
  const alias = database.notes;
  expect.true(remove(database, 2));
  expect.equal(alias.length(), 2);
  expect.true(identity.same(alias[0], first));
  expect.true(identity.same(alias[1], last));
  expect.equal(database.nextId, 4);
  expect.false(remove(database, 2));
  expect.equal(alias.length(), 2);
  expect.true(remove(database, 1));
  expect.true(identity.same(alias[0], last));
  expect.true(remove(database, 3));
  expect.equal(alias.length(), 0);
  expect.false(remove(database, 3));
}

@test
fn searchReturnsTheStoredRecord(): void {
  const first = Note { id: 2, text: "🌿", tags: ["язык"] };
  const last = Note { id: 8, text: "🌿", tags: [] };
  const database = Database { version: 1, nextId: 9, notes: [first, last] };
  const found = match find(database, 8) {
    Some(value) => value,
    None => panic("stored note was not found"),
  };
  expect.true(identity.same(found, last));
  expect.true(
    match find(database, 7) {
      Some(_) => false,
      None => true,
    },
  );
  expect.equal(database.notes.length(), 2);
}

@test
fn rejectedAddPreservesNonemptyInput(): void {
  const note = Note { id: 1, text: "сохранить", tags: ["важно"] };
  const database = Database { version: 1, nextId: 2, notes: [note] };
  expect.err(add(database, " \t", ["другой"]));
  expect.equal(database.notes.length(), 1);
  expect.equal(database.nextId, 2);
  expect.true(identity.same(database.notes[0], note));
  expect.equal(note.tags[0], "важно");
}

