    ReadFailed => "Не удалось прочитать стандартный ввод",
    WriteFailed => "Не удалось вывести сообщение",
    FlushFailed => "Не удалось завершить вывод",
    InvalidUtf8 => "Ввод содержит некорректный UTF-8",
    LineTooLong { limit } => $"Строка превышает допустимую длину: {limit} байт",
    InputTooLong { limit } => $"Ввод превышает допустимый размер: {limit} байт",
  };
}

public fn usageError(error: cli.UsageError): string {
  return match error {
    TooManyArguments { limit } => $"Слишком много аргументов: допускается не больше {limit}",
    UnknownOption { argument, index } => $"Неизвестный параметр «{argument}». Справка: --help",
    UnexpectedOptionValue { name, index } => $"Параметр --{name} не принимает значение",
    MissingOptionValue { name, index } => $"После --{name} нужно указать значение",
    RepeatedOption { name, index } => $"Параметр --{name} нельзя указывать несколько раз",
    UnexpectedPositional { value, index } => $"Лишний аргумент «{value}»",
    MissingRequiredOption { name } => $"Не указан обязательный параметр --{name}",
    MissingRequiredPositional { name } => $"Не указан обязательный аргумент «{name}»",
  };
}

